def days_to_end_of_year(y, m, d):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
    dim = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    doy = sum(dim[:m - 1]) + d
    total_days = 366 if is_leap(y) else 365
    return total_days - doy

def date_n_days_before_year_end(year, n):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    total_days = 366 if is_leap(year) else 365
    doy = total_days - n
    m = 1
    while doy > dim[m - 1]:
        doy -= dim[m - 1]
        m += 1
    return (m, doy)

def first_day_of_next_month(y, m, d):
    if m == 12:
        return (y + 1, 1, 1)
    return (y, m + 1, 1)
